$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot

$migrationPath = Join-Path $root "supabase\migrations\20260812195600_klyx_multi_slot_market_12_83.sql"
$proofPath = Join-Path $root "lib\brain-multi-slot-proof.ts"
$matchingPath = Join-Path $root "lib\market-multi-slot.ts"
$confirmPath = Join-Path $root "app\api\brain\confirm-request\route.ts"
$publishPath = Join-Path $root "app\api\brain\market-publish-multi\route.ts"
$multiPagePath = Join-Path $root "app\request\confirm-multi\page.tsx"
$brainPath = Join-Path $root "app\brain\page.tsx"
$respondPath = Join-Path $root "app\api\brain\respond\route.ts"

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $publishPath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $multiPagePath) | Out-Null
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $migrationPath) | Out-Null

$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$migration = Decode ""
$proof = Decode ""
$matching = Decode ""
$confirm = Decode ""
$publish = Decode ""
$page = Decode ""
$payloadOld = Decode ""
$payloadNew = Decode ""
$mergeOld = Decode "ICBpZiAoIXBheWxvYWQpIHJldHVybiBudWxsOwoKICBjb25zdCBkZXRlY3RlZFRpbWUgPSBwYXlsb2FkLnRpbWUgPz8gZGV0ZWN0VGltZUxvY2FsbHkobWVzc2FnZSk7"
$mergeNew = Decode "ICBpZiAoIXBheWxvYWQpIHJldHVybiBudWxsOwoKICAvLyBLTFlYX01VTFRJX1NMT1RfQlJBSU5fVUlfMTJfODMKICBpZiAocGF5bG9hZC5zY2hlZHVsZT8ubXVsdGlTbG90KSB7CiAgICByZXR1cm4gcGF5bG9hZDsKICB9CgogIGNvbnN0IGRldGVjdGVkVGltZSA9IHBheWxvYWQudGltZSA/PyBkZXRlY3RUaW1lTG9jYWxseShtZXNzYWdlKTs="
$replyOld = Decode "ICAgICAgbGV0IGZpbmFsUmVwbHkgPQogICAgICAgIHVuZGVyc3Rvb2RQYXlsb2FkPy5yZWFkeQogICAgICAgICAgPyBidWlsZE5hdHVyYWxDb25maXJtYXRpb24odW5kZXJzdG9vZFBheWxvYWQpCiAgICAgICAgICA6IHN0cnVjdHVyZWRSZXN1bHQucmVwbHk7"
$replyNew = Decode ""
$confirmOld = Decode "ICAgICAgICAgICAgYnVkZ2V0OiBwYXlsb2FkLmJ1ZGdldCwKICAgICAgICAgIH0s"
$confirmNew = Decode "ICAgICAgICAgICAgYnVkZ2V0OiBwYXlsb2FkLmJ1ZGdldCwKICAgICAgICAgICAgc2NoZWR1bGU6IHBheWxvYWQuc2NoZWR1bGUgPz8gbnVsbCwKICAgICAgICAgIH0s"
$openOld = Decode "ICAgIGNvbnN0IHBhcmFtcyA9IG5ldyBVUkxTZWFyY2hQYXJhbXMoKTsKCiAgICBpZiAocGF5bG9hZC5zZXJ2aWNlU2x1Zykgew=="
$openNew = Decode ""
$respondBlock = Decode ""

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

foreach ($path in @($confirmPath, $brainPath, $respondPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "Fichier requis introuvable : $path"
    }

    Copy-Item -LiteralPath $path -Destination ($path + ".bak-12-83-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($migrationPath, $migration, $utf8)
[System.IO.File]::WriteAllText($proofPath, $proof, $utf8)
[System.IO.File]::WriteAllText($matchingPath, $matching, $utf8)
[System.IO.File]::WriteAllText($confirmPath, $confirm, $utf8)
[System.IO.File]::WriteAllText($publishPath, $publish, $utf8)
[System.IO.File]::WriteAllText($multiPagePath, $page, $utf8)

$brain = [System.IO.File]::ReadAllText($brainPath)

if (-not $brain.Contains("KLYX_MULTI_SLOT_BRAIN_UI_12_83")) {
    foreach ($pair in @(
        @($payloadOld, $payloadNew),
        @($mergeOld, $mergeNew),
        @($replyOld, $replyNew),
        @($confirmOld, $confirmNew),
        @($openOld, $openNew)
    )) {
        if (-not $brain.Contains($pair[0])) {
            throw "12.83 : ancre Brain introuvable."
        }

        $brain = $brain.Replace($pair[0], $pair[1])
    }
}

[System.IO.File]::WriteAllText($brainPath, $brain, $utf8)

$respond = [System.IO.File]::ReadAllText($respondPath)

if (-not $respond.Contains("KLYX_MULTI_SLOT_PUBLISH_READY_12_83")) {
    if (-not $respond.Contains("KLYX_MULTI_SLOT_INTEGRATION_12_82")) {
        throw "KLYX 12.82 introuvable dans Brain respond."
    }

    if ($respond.Contains($respondBlock)) {
        $respond = $respond.Replace($respondBlock, "")
    }
    elseif ($respond.Contains("publication_multi_creneaux")) {
        throw "Bloc publication_multi_creneaux present mais format inattendu."
    }

    $anchor = "    const ready =`n      missing.length === 0;"

    if (-not $respond.Contains($anchor)) {
        throw "Ancre ready Brain introuvable."
    }

    $replacement = "    // KLYX_MULTI_SLOT_PUBLISH_READY_12_83`n" + $anchor
    $respond = $respond.Replace($anchor, $replacement)
}

[System.IO.File]::WriteAllText($respondPath, $respond, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.83 APPLIQUE"
Write-Host "======================================"
Write-Host "Parent Market groupe : OK"
Write-Host "Creneaux enfants : OK"
Write-Host "Confirmation multi-creneaux : OK"
Write-Host "Matching tous les creneaux : OK"
Write-Host "Priorite meme prestataire : OK"
Write-Host ""
